"use client";

/**
 * Due-date control that flags overdue values.
 */
import { DatePicker } from "@/components/ui/date-picker";
import { toIsoTimestamp } from "@/types/common";
import { isOverdue } from "@/lib/date";
import type { IsoTimestamp } from "@/types/common";
import type { ReactElement } from "react";

export type IssueDueDateFieldProps = {
  value: IsoTimestamp | null;
  onChange: (value: IsoTimestamp | null) => void;
};

/** The picker speaks `YYYY-MM-DD`; the domain stores full ISO timestamps. */
export function toDateInputValue(value: IsoTimestamp | null): string | null {
  return value === null ? null : value.slice(0, 10);
}

export function fromDateInputValue(value: string | null): IsoTimestamp | null {
  if (value === null || value.length === 0) return null;
  // End of day: an issue due "today" is not overdue at 09:00.
  return toIsoTimestamp(new Date(`${value}T23:59:59.999Z`));
}

export function IssueDueDateField(
  props: IssueDueDateFieldProps,
): ReactElement | null {
  const overdue = isOverdue(props.value);

  return (
    <div className="space-y-1">
      <DatePicker
        value={toDateInputValue(props.value)}
        placeholder="No due date"
        onChange={(value) => props.onChange(fromDateInputValue(value))}
      />
      {overdue ? (
        <p className="text-xs text-red-600">This issue is past its due date.</p>
      ) : null}
    </div>
  );
}
"use client";

/**
 * Single-line text field.
 *
 * Owner A — design system. Controlled when `value` is supplied, uncontrolled
 * when only `defaultValue` is: react-hook-form drives it either way and
 * `onChange` hands back the string rather than the event, so domain forms never
 * touch `event.target`.
 */
import type { ChangeEvent, ReactElement } from "react";
import { cn } from "@/lib/cn";
import {
  CONTROL_BASE,
  CONTROL_BORDER,
  CONTROL_INVALID,
  FOCUS_RING,
} from "./_lib/tokens";

export type InputProps = { name: string; value?: string; defaultValue?: string; placeholder?: string; type?: 'text' | 'email' | 'password' | 'search' | 'url'; invalid?: boolean; disabled?: boolean; onChange?: (value: string) => void; className?: string };

export function Input(props: InputProps): ReactElement | null {
  const {
    name,
    value,
    defaultValue,
    placeholder,
    type = "text",
    invalid = false,
    disabled = false,
    onChange,
    className,
  } = props;

  const controlled = value !== undefined;

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    onChange?.(event.target.value);
  };

  return (
    <input
      id={name}
      name={name}
      type={type}
      placeholder={placeholder}
      disabled={disabled}
      aria-invalid={invalid || undefined}
      aria-errormessage={invalid ? `${name}-error` : undefined}
      // React warns when a field flips between controlled and uncontrolled, so
      // exactly one of the two props reaches the DOM node.
      value={controlled ? value : undefined}
      defaultValue={controlled ? undefined : defaultValue}
      onChange={handleChange}
      className={cn(
        CONTROL_BASE,
        "h-9",
        invalid ? CONTROL_INVALID : CONTROL_BORDER,
        FOCUS_RING,
        className,
      )}
    />
  );
}
/**
 * Display formatting for money, counts, byte sizes and enum labels.
 *
 * The humanizers here are the only place a domain enum turns into prose —
 * components render `humanizeStatus(issue.status)` rather than carrying their
 * own label maps, so a new status value shows up consistently everywhere.
 */
import { UNLIMITED } from "@/config/plan-limits";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import type { Role } from "@/types/member";

export function formatCents(cents: number, currency = "USD"): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
    minimumFractionDigits: 2,
  }).format(cents / 100);
}

/** 1_234 → "1,234"; 12_400 → "12.4K"; 3_100_000 → "3.1M". */
export function formatCount(value: number): string {
  const abs = Math.abs(value);
  if (abs < 10_000) return new Intl.NumberFormat("en-US").format(value);
  if (abs < 1_000_000) return `${trimZero(value / 1_000)}K`;
  return `${trimZero(value / 1_000_000)}M`;
}

function trimZero(value: number): string {
  return value.toFixed(1).replace(/\.0$/, "");
}

const BYTE_UNITS = ["B", "KB", "MB", "GB", "TB"] as const;

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${Math.round(bytes)} B`;
  let value = bytes;
  let unit = 0;
  while (value >= 1024 && unit < BYTE_UNITS.length - 1) {
    value /= 1024;
    unit += 1;
  }
  return `${trimZero(value)} ${BYTE_UNITS[unit]}`;
}

/** Renders a plan quota, including the `Infinity` "no limit" sentinel. */
export function formatLimit(limit: number): string {
  return limit === UNLIMITED || !Number.isFinite(limit)
    ? "Unlimited"
    : formatCount(limit);
}

const STATUS_LABELS: Readonly<Record<IssueStatus, string>> = {
  backlog: "Backlog",
  todo: "Todo",
  in_progress: "In progress",
  in_review: "In review",
  done: "Done",
  canceled: "Canceled",
};

const PRIORITY_LABELS: Readonly<Record<IssuePriority, string>> = {
  none: "No priority",
  low: "Low",
  medium: "Medium",
  high: "High",
  urgent: "Urgent",
};

const ROLE_LABELS: Readonly<Record<Role, string>> = {
  owner: "Owner",
  admin: "Admin",
  member: "Member",
  viewer: "Viewer",
};

export function humanizeStatus(status: IssueStatus): string {
  return STATUS_LABELS[status];
}

export function humanizePriority(priority: IssuePriority): string {
  return PRIORITY_LABELS[priority];
}

export function humanizeRole(role: Role): string {
  return ROLE_LABELS[role];
}

/** The short reference shown on cards and in links, e.g. "TF-142". */
export function issueKey(projectKey: string, issueNumber: number): string {
  return `${projectKey.toUpperCase()}-${issueNumber}`;
}
import { describe, expect, it } from "vitest";
import {
  activeFilterCount,
  issueFilterQueryString,
  issueFilterToParams,
  parseIssueFilterParams,
  UNASSIGNED_TOKEN,
} from "@/hooks/issue-filter-params";
import type { LabelId, ProjectId, UserId } from "@/types/common";
import type { IssueFilter } from "@/types/issue";

function params(query: string): URLSearchParams {
  return new URLSearchParams(query);
}

describe("issue-filter-params/parse", () => {
  it("returns an empty filter for an empty query string", () => {
    expect(parseIssueFilterParams(params(""))).toEqual({});
  });

  it("parses comma-separated statuses and drops unknown values", () => {
    const filter = parseIssueFilterParams(params("status=todo,nonsense,done"));
    expect(filter.status).toEqual(["todo", "done"]);
  });

  it("distinguishes unassigned from no assignee filter", () => {
    expect(parseIssueFilterParams(params("assignee=none")).assigneeId).toBeNull();
    expect("assigneeId" in parseIssueFilterParams(params(""))).toBe(false);
  });

  it("reads the archived flag only for the literal 1", () => {
    expect(parseIssueFilterParams(params("archived=1")).includeArchived).toBe(
      true,
    );
    expect(
      parseIssueFilterParams(params("archived=true")).includeArchived,
    ).toBeUndefined();
  });
});

describe("issue-filter-params/serialise", () => {
  const filter: IssueFilter = {
    projectId: "prj_1" as ProjectId,
    status: ["todo", "in_progress"],
    assigneeId: "usr_1" as UserId,
    labelIds: ["lbl_1" as LabelId, "lbl_2" as LabelId],
    query: "crash",
    includeArchived: true,
  };

  it("round-trips through the query string", () => {
    const restored = parseIssueFilterParams(
      params(new URLSearchParams(issueFilterToParams(filter)).toString()),
    );
    expect(restored).toEqual(filter);
  });

  it("omits empty dimensions entirely", () => {
    expect(issueFilterToParams({ status: [], labelIds: [], query: "" })).toEqual(
      {},
    );
  });

  it("writes unassigned as the sentinel token", () => {
    expect(issueFilterToParams({ assigneeId: null }).assignee).toBe(
      UNASSIGNED_TOKEN,
    );
  });

  it("produces a bare path for an empty filter", () => {
    expect(issueFilterQueryString({})).toBe("");
    expect(issueFilterQueryString({ query: "x" })).toBe("?q=x");
  });

  it("counts the narrowed dimensions", () => {
    expect(activeFilterCount({})).toBe(0);
    expect(activeFilterCount(filter)).toBe(6);
  });
});
